"""Writes this Parquet copy of Calliope's `tests/example_models/national_scale_from_data_tables`.

Every table is read as Calliope's `DataTable` reads it (`pd.read_csv` with one header row
per `columns` level and one index column per `rows` level) and saved with
`DataFrame.to_parquet` (pyarrow, snappy). `time_varying.parquet` is the in-memory table of
the upstream test (first five days only); `time_varying_datetime.parquet` has the same data on a
`DatetimeIndex`.

Usage: python gen.py <calliope checkout>
"""

import re
import sys
from pathlib import Path

import pandas as pd
import yaml


def listify(x):
    return [] if x is None else ([x] if isinstance(x, str) else x)


ref = Path(sys.argv[1])
here = Path(__file__).parent
src = ref / "tests" / "example_models" / "national_scale_from_data_tables"
text = (src / "model.yaml").read_text()
defs = yaml.safe_load(text)["data_tables"]
(here / "data_tables").mkdir(exist_ok=True)
for d in defs.values():
    table = d["table"]
    if not table.endswith(".csv"):
        continue
    cols, rows = listify(d.get("columns")), listify(d.get("rows"))
    df = pd.read_csv(
        src / table,
        header=list(range(len(cols))) if cols else [0],
        index_col=list(range(len(rows))) if rows else None,
    )
    df.to_parquet(here / table.replace(".csv", ".parquet"))

tv = pd.read_csv(
    ref
    / "src/calliope/example_models/national_scale/data_tables/time_varying_params.csv",
    index_col=0,
    header=[0, 1, 2, 3],
).iloc[:120]  # 2005-01-01 to 2005-01-05, the model's subset
tv.to_parquet(here / "data_tables" / "time_varying.parquet")
tv.index = pd.to_datetime(tv.index)
tv.to_parquet(here / "data_tables" / "time_varying_datetime.parquet")

text = re.sub(r"(data_tables/\w+)\.csv", r"\1.parquet", text)
text = text.replace("table: time_varying_df", "table: data_tables/time_varying.parquet")
(here / "model.yaml").write_text(
    "# Generated by gen.py from Calliope's national_scale_from_data_tables.\n" + text
)
